6: 
7: class SqfliteDatasourceImpl implements DbDatasource {
8:   final DatabaseHelper _helper = DatabaseHelper();
9: 
10:   @override
11:   Future<List<CurrencyModel>> getCurrencyList() async {
12:     final Database db = await _helper.database;
13:     final List<Map<String, dynamic>> maps = await db.query(CurrencyTable.name);
14: 
15:     return maps.map((e) => CurrencyModelDbMapper.fromMap(e)).toList(growable: false);
16:   }
17: 
18:   @override
19:   Future<List<NewsModel>> getNewsList() async {
20:     final Database db = await _helper.database;
21:     final List<Map<String, dynamic>> maps = await db.query(NewsTable.name);
22: 
23:     return maps.map((e) => NewsModelDbMapper.fromMap(e)).toList(growable: false);
24:   }
25: 
26:   @override
27:   Future<void> saveCurrencyList(List<CurrencyModel> value) async {
28:     final Database db = await _helper.database;
29:     final Batch batch = db.batch();
30: 
31:     for (final CurrencyModel item in value) {
32:       batch.insert(
33:         CurrencyTable.name,
34:         item.toMap(),
35:         conflictAlgorithm: ConflictAlgorithm.replace,
36:       );
37:     }
38: 
39:     await batch.commit(noResult: true);
40:   }
41: 
42:   @override
43:   Future<void> saveNewsList(List<NewsModel> value) async {
44:     final Database db = await _helper.database;
45:     final Batch batch = db.batch();
46: 
47:     for (final NewsModel item in value) {
48:       batch.insert(
49:         NewsTable.name,
50:         item.toMap(),
51:         conflictAlgorithm: ConflictAlgorithm.replace,
52:       );
53:     }
54: 
55:     await batch.commit(noResult: true);
