8: class NewsListPage extends StatefulWidget {
9:   const NewsListPage({super.key});
10: 
11:   @override
12:   State<NewsListPage> createState() => _NewsListPageState();
13: }
14: 
15: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
16:   static final _tween = Tween<double>(begin: 0.25, end: 1);
17: 
18:   late final AnimationController _scaleController;
19:   late final Animation<double> _scaleAnimation;
20: 
21:   StreamSubscription<List<NewsModel>>? _freshSubscription;
22: 
23:   List<NewsModel> _newsList = const [];
24: 
25:   @override
26:   void initState() {
27:     super.initState();
28:     _initAnimation();
29:     _initData();
30:   }
31: 
32:   @override
33:   void dispose() {
34:     _freshSubscription?.cancel();
35:     _scaleController.dispose();
36:     super.dispose();
37:   }
38: 
39:   void _initAnimation() {
40:     _scaleController = AnimationController(
41:       vsync: this,
42:       duration: Duration(milliseconds: 200),
43:     );
44:     _scaleAnimation = _tween.animate(_scaleController);
45:   }
46: 
47:   Future<void> _initData() async {
48:     final newsRepository = context.read<NewsRepository>();
49:     final NewsFeed feed;
50: 
51:     try {
52:       feed = await newsRepository.watchNewsFeed(const NewsFeedFilter());
53:     } on Object {
54:       return; // кэш недоступен — показываем пустой список
55:     }
56: 
57:     if (!mounted) return;
58: 
59:     // Мгновенно показываем кэш, если он есть.
60:     if (feed.cached.isNotEmpty) {
61:       _updateNewsList(feed.cached);
62:     }
63: 
64:     // Параллельно ждём сеть и обновляем список, когда придёт ответ.
65:     _freshSubscription = feed.freshStream.listen(
66:       _updateNewsList,
67:       onError: (Object _) {}, // сеть недоступна — остаётся показанный кэш
68:     );
69:   }
70: 
71:   void _updateNewsList(List<NewsModel> value) {
72:     if (!mounted) return;
73: 
74:     setState(() {
75:       _newsList = value;
76:     });
